interface Component {
  render(): string;
}

class Leaf implements Component {
  constructor(private text: string) {}
  render() { return this.text; }
}

class Container implements Component {
  private children: Component[] = [];
  add(c: Component) { this.children.push(c); }
  render() { return this.children.map(c => c.render()).join('\n'); }
}

abstract class Node {}
class File extends Node { size = 10 }
class Folder extends Node { children: Node[] = [] }

function totalSize(nodes: Node[]) {
  return nodes.reduce((sum, n) => {
    if (n instanceof Folder) return sum + totalSize(n.children);
    return sum + (n as File).size;
  }, 0);
}

// Version A: client inspects types
interface Node {}
class File implements Node { constructor(public size: number) {} }
class Folder implements Node { constructor(public children: Node[]) {} }
function totalA(nodes: Node[]): number {
  let sum = 0;
  for (const n of nodes) {
    if (n instanceof Folder) sum += totalA((n as Folder).children);
    else sum += (n as File).size;
  }
  return sum;
}

// Version B: polymorphic operation on nodes
interface Node2 { totalSize(): number }
class File2 implements Node2 { constructor(private size: number) {} totalSize() { return this.size } }
class Folder2 implements Node2 { constructor(private children: Node2[]) {} totalSize() { return this.children.reduce((s, c) => s + c.totalSize(), 0) } }
